/*
 * Generated from e2e/features/homepage/SMOKE-homepage-load.feature
 * Smoke test — no Jira story, see e2e/features/README.md > Smoke tests (no Jira story).
 */

const { test, expect } = require('@playwright/test');
const { HomePage } = require('../../../support/pages/HomePage');

test('Homepage loads successfully', { tag: ['@homepage', '@smoke'] }, async ({ page }) => {
  const homePage = new HomePage(page);
  const response = await homePage.goToHomepage();

  expect(response.status()).toBe(200);
  await expect(homePage.logo).toBeVisible();
});

test('Clicking the logo keeps me on the homepage', { tag: ['@homepage', '@smoke'] }, async ({ page }) => {
  const homePage = new HomePage(page);
  await homePage.goToHomepage();
  const homepageUrl = page.url();

  await homePage.clickLogo();

  await expect(page).toHaveURL(homepageUrl);
});

